    if len(rest)>need:
        return unexpected(rest[need], USAGE[f"env {sub}"])
    if not is_uint(rest[0]): return invalid_value(rest[0], "<TASK_ID>")
    return None


def parse_group(args):
    if not args:
        return None
    if args[0] in ("-h","--help"):
        return print_help_for(["group"], long=args[0]=="--help")
    if args[0] == "help":
        if len(args) >= 2 and args[1] in ("add","remove"):
            return print_help_for(["group",args[1]], True)
        return print_help_for(["group"], True)
    if args[0] in ("-j","--json"):
        if len(args)==1: return None
        return unexpected(args[1], USAGE["group"])
    sub=args[0]
    if sub not in ("add","remove"):
        return unrecognized_subcommand(sub, USAGE["group"], None)
    rest=args[1:]
    if "--help" in rest or "-h" in rest:
        return print_help_for(["group",sub], long=("--help" in rest))
    if sub=="remove":
        if len(rest)<1: return missing_arg("<NAME>", USAGE["group remove"])
        if len(rest)>1: return unexpected(rest[1], USAGE["group remove"])
        return None
    # add
    pos=[]; i=0
    while i<len(rest):
        a=rest[i]
        if a in ("-p","--parallel") or a.startswith("--parallel="):
            val,ni,rc=get_opt_value(rest,i,"--parallel <PARALLEL>")
            if rc is not None: return rc
            if not is_uint(val): return invalid_value(val,"--parallel <PARALLEL>")
            i=ni; continue
        if a.startswith('-'):
            return unexpected(a, USAGE["group add"], value_tip=True)
        pos.append(a); i+=1
    if not pos: return missing_arg("<NAME>", USAGE["group_add_required"])
    if len(pos)>1: return unexpected(pos[1], USAGE["group add"])
    return None


def do_completions(args):
    if "--help" in args or "-h" in args:
        return print_help_for(["completions"], long=("--help" in args))
    if len(args)<1:
        return missing_arg("<SHELL>", USAGE["completions"])
    shell=args[0]
    if shell not in SHELLS:
        tip = None
        m = difflib.get_close_matches(shell, SHELLS, n=1, cutoff=0.3)
        if m: tip = f"a similar value exists: '{m[0]}'"
        return parse_error(f"invalid value '{shell}' for '<SHELL>'", possible=SHELLS, tip=tip)
    if len(args)>2:
        return unexpected(args[2], USAGE["completions"])
    data=load_text(OBS / "completions" / f"{shell}.txt")
    if len(args)==2:
        outdir=Path(args[1])
        try:
            outdir.mkdir(parents=False, exist_ok=True)
            (outdir / COMP_FILES[shell]).write_text(data)
        except Exception as ex:
            return error_report([f"I/O error at path \"{args[1]}\" while writing completion file:\n      {ex}"], "pueue/src/bin/pueue.rs", 1)
    else:
        out(data)
    return 0


def main():
    config, profile, help_kind, rest = parse_global(sys.argv[1:])
    if help_kind and not rest:
        return print_help_for([], long=(help_kind=="long"))
    if not rest:
        return load_config_and_fail(config, profile)
    cmd_token = rest[0]
    if cmd_token == "help":
        if len(rest)==1:
            return print_help_for([], True)
        target = rest[1:]
        first = target[0]
        if first not in CANON or CANON[first] == "help":
            return unrecognized_subcommand(first, USAGE["root"], VISIBLE+HIDDEN)
        return print_help_for(target, True)
    if cmd_token not in CANON or CANON[cmd_token] == "help":
        return unrecognized_subcommand(cmd_token, USAGE["root"], VISIBLE+HIDDEN)
    canon=CANON[cmd_token]
    args=rest[1:]
    if help_kind:
        return print_help_for([cmd_token], long=(help_kind=="long"))
    if canon == "completions":
        return do_completions(args)
    if canon == "add":
        rc=parse_add(args)
    elif canon == "env":
        rc=parse_env(args)
    elif canon == "group":
        rc=parse_group(args)
    else:
        rc=parse_simple_command(canon,args)
    if rc is not None:
        return rc
    return load_config_and_fail(config, profile)

if __name__ == "__main__":
    sys.exit(main())
