                    return invalid_value(val, "--lines <LINES>")
                if opt in ("-s","--signal") and cmd == "kill":
                    sigs = {"hup","int","quit","ill","trap","abrt","bus","fpe","kill","usr1","segv","usr2","pipe","alrm","term","stkflt","chld","cont","stop","tstp","ttin","ttou","urg","xcpu","xfsz","vtalrm","prof","winch","io","pwr","sys"}
                    vv=val.lower().removeprefix("sig")
                    if not is_uint(val) and vv not in sigs:
                        return invalid_value(val, "--signal <SIGNAL>", "Matching variant not found")
                if cmd == "parallel" and opt not in ("-g","--group") and val and not is_uint(val):
                    return invalid_value(val, "[PARALLEL_TASKS]")
                i=ni; continue
            return unexpected(a, USAGE[cmd], value_tip=(maxp is None or maxp>0))
        pos.append(a); i+=1
    if len(pos) < minp:
        if cmd == "switch":
            return missing_arg("<TASK_ID_2>" if len(pos)==1 else ["<TASK_ID_1>","<TASK_ID_2>"], USAGE[cmd])
        if cmd == "send":
            return missing_arg("<INPUT>" if len(pos)==1 else ["<TASK_ID>","<INPUT>"], USAGE[cmd])
        return missing_arg("<TASK_IDS>...", USAGE[cmd])
    if maxp is not None and len(pos) > maxp:
        return unexpected(pos[maxp], USAGE[cmd])
    # validate numeric positionals
    if cmd == "switch":
        if not is_uint(pos[0]): return invalid_value(pos[0], "<TASK_ID_1>")
        if not is_uint(pos[1]): return invalid_value(pos[1], "<TASK_ID_2>")
    elif cmd == "send":
        if not is_uint(pos[0]): return invalid_value(pos[0], "<TASK_ID>")
    elif cmd == "parallel":
        if pos and not is_uint(pos[0]): return invalid_value(pos[0], "[PARALLEL_TASKS]")
    elif task and target:
        rc = parse_task_ids(pos, target)
        if rc is not None: return rc
    return None


def parse_add(args):
    if "--help" in args or "-h" in args:
        return print_help_for(["add"], long=("--help" in args))
    pos=[]; i=0; dd=False
    while i < len(args):
        a=args[i]
        if not dd and a == "--": dd=True; i+=1; continue
        if not dd and a.startswith('-'):
            if a in ("-e","--escape","-i","--immediate","--follow","-s","--stashed","-p","--print-task-id"):
                i+=1; continue
            display_map={"-w":"--working-directory <working-directory>","--working-directory":"--working-directory <working-directory>","-d":"--delay <delay>","--delay":"--delay <delay>","-g":"--group <GROUP>","--group":"--group <GROUP>","-o":"--priority <PRIORITY>","--priority":"--priority <PRIORITY>","-l":"--label <LABEL>","--label":"--label <LABEL>"}
            matched = None
            for k in list(display_map):
                if a == k or (k.startswith('--') and a.startswith(k+'=')):
                    matched = k; break
            if matched:
                val, ni, rc = get_opt_value(args,i,display_map[matched])
                if rc is not None: return rc
                if matched in ("-o","--priority") and not is_uint(val):
                    return invalid_value(val, "--priority <PRIORITY>")
                i=ni; continue
            if a in ("-a","--after") or a.startswith("--after="):
                first = None
                if a.startswith("--after="):
                    first = a.split("=",1)[1]; i += 1
                else:
                    if i+1 >= len(args): return missing_value("--after <after>...")
                    i += 1; first = args[i]; i += 1
                vals=[first]
                while i < len(args) and args[i] != "--" and not args[i].startswith('-'):
                    vals.append(args[i]); i += 1
                for v in vals:
                    if not is_uint(v): return invalid_value(v, "--after <after>...")
                continue
            return unexpected(a, USAGE["add"], value_tip=True)
        pos.append(a); i+=1
    if not pos:
        return missing_arg("<COMMAND>...", USAGE["add_required"])
    return None


def parse_env(args):
    if not args:
        err(read_help("env", False)); return 2
    if args[0] in ("-h","--help"):
        return print_help_for(["env"], long=args[0]=="--help")
    if args[0] == "help":
        if len(args) >= 2 and args[1] in ("set","unset"):
            return print_help_for(["env",args[1]], True)
        return print_help_for(["env"], False)
    sub=args[0]
    if sub not in ("set","unset"):
        return unrecognized_subcommand(sub, USAGE["env"], None)
    rest=args[1:]
    if "--help" in rest or "-h" in rest:
        return print_help_for(["env",sub], long=("--help" in rest))
    need=3 if sub=="set" else 2
    names=["<TASK_ID>","<KEY>"] + (["<VALUE>"] if sub=="set" else [])
    if len(rest)<need:
        return missing_arg(names[len(rest)], USAGE[f"env {sub}"])
    if len(rest)>need:
        return unexpected(rest[need], USAGE[f"env {sub}"])
    if not is_uint(rest[0]): return invalid_value(rest[0], "<TASK_ID>")
    return None


def parse_group(args):
    if not args:
        return None
    if args[0] in ("-h","--help"):
        return print_help_for(["group"], long=args[0]=="--help")
    if args[0] == "help":
        if len(args) >= 2 and args[1] in ("add","remove"):
            return print_help_for(["group",args[1]], True)
        return print_help_for(["group"], True)
    if args[0] in ("-j","--json"):
        if len(args)==1: return None
        return unexpected(args[1], USAGE["group"])
    sub=args[0]
    if sub not in ("add","remove"):
        return unrecognized_subcommand(sub, USAGE["group"], None)
    rest=args[1:]
    if "--help" in rest or "-h" in rest:
        return print_help_for(["group",sub], long=("--help" in rest))
    if sub=="remove":
        if len(rest)<1: return missing_arg("<NAME>", USAGE["group remove"])
        if len(rest)>1: return unexpected(rest[1], USAGE["group remove"])
        return None
    # add
    pos=[]; i=0
    while i<len(rest):
        a=rest[i]
        if a in ("-p","--parallel") or a.startswith("--parallel="):
            val,ni,rc=get_opt_value(rest,i,"--parallel <PARALLEL>")
            if rc is not None: return rc
            if not is_uint(val): return invalid_value(val,"--parallel <PARALLEL>")
            i=ni; continue
        if a.startswith('-'):
            return unexpected(a, USAGE["group add"], value_tip=True)
        pos.append(a); i+=1
    if not pos: return missing_arg("<NAME>", USAGE["group_add_required"])
    if len(pos)>1: return unexpected(pos[1], USAGE["group add"])
    return None


def do_completions(args):
    if "--help" in args or "-h" in args:
        return print_help_for(["completions"], long=("--help" in args))
    if len(args)<1:
        return missing_arg("<SHELL>", USAGE["completions"])
    shell=args[0]
    if shell not in SHELLS:
        tip = None
        m = difflib.get_close_matches(shell, SHELLS, n=1, cutoff=0.3)
        if m: tip = f"a similar value exists: '{m[0]}'"
        return parse_error(f"invalid value '{shell}' for '<SHELL>'", possible=SHELLS, tip=tip)
    if len(args)>2:
        return unexpected(args[2], USAGE["completions"])
    data=load_text(OBS / "completions" / f"{shell}.txt")
    if len(args)==2:
        outdir=Path(args[1])
        try:
            outdir.mkdir(parents=False, exist_ok=True)
            (outdir / COMP_FILES[shell]).write_text(data)
        except Exception as ex:
            return error_report([f"I/O error at path \"{args[1]}\" while writing completion file:\n      {ex}"], "pueue/src/bin/pueue.rs", 1)
    else:
        out(data)
    return 0


def main():
    config, profile, help_kind, rest = parse_global(sys.argv[1:])
    if help_kind and not rest:
        return print_help_for([], long=(help_kind=="long"))
    if not rest:
        return load_config_and_fail(config, profile)
    cmd_token = rest[0]
    if cmd_token == "help":
        if len(rest)==1:
            return print_help_for([], True)
        target = rest[1:]
        first = target[0]
        if first not in CANON or CANON[first] == "help":
            return unrecognized_subcommand(first, USAGE["root"], VISIBLE+HIDDEN)
        return print_help_for(target, True)
    if cmd_token not in CANON or CANON[cmd_token] == "help":
        return unrecognized_subcommand(cmd_token, USAGE["root"], VISIBLE+HIDDEN)
    canon=CANON[cmd_token]
    args=rest[1:]
    if help_kind:
        return print_help_for([cmd_token], long=(help_kind=="long"))
    if canon == "completions":
        return do_completions(args)
    if canon == "add":
        rc=parse_add(args)
    elif canon == "env":
        rc=parse_env(args)
    elif canon == "group":
        rc=parse_group(args)
    else:
        rc=parse_simple_command(canon,args)
    if rc is not None:
        return rc
    return load_config_and_fail(config, profile)

if __name__ == "__main__":
    sys.exit(main())
